package com.gk.jobhelper.service;
import com.gk.jobhelper.common.ApiResponse;import com.gk.jobhelper.common.BusinessException;import com.gk.jobhelper.dto.RecruitmentSourceCreateRequest;import com.gk.jobhelper.entity.RecruitmentSource;import com.gk.jobhelper.mapper.RecruitmentSourceMapper;import java.net.URI;import java.time.LocalDateTime;import java.util.List;import java.util.Locale;import java.util.UUID;import org.springframework.stereotype.Service;
@Service public class RecruitmentSourceService {private final RecruitmentSourceMapper sources;public RecruitmentSourceService(RecruitmentSourceMapper s){sources=s;}public List<RecruitmentSource> list(){return sources.selectAll();}public RecruitmentSource create(RecruitmentSourceCreateRequest request){String name=request.getSourceName().trim(),url=validUrl(request.getListUrl());LocalDateTime now=LocalDateTime.now();RecruitmentSource source=new RecruitmentSource();source.setSourceCode("CUSTOM_"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT));source.setSourceName(name);source.setSourceType("GENERIC_WEB");source.setListUrl(url);source.setEnabled(true);source.setCreatedAt(now);source.setUpdatedAt(now);sources.insert(source);return source;}public void updateEnabled(Long id,boolean enabled){if(id==null||sources.updateEnabled(id,enabled,LocalDateTime.now())!=1)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"招聘网站不存在");}private String validUrl(String value){try{URI uri=URI.create(value.trim());if(!"http".equalsIgnoreCase(uri.getScheme())&&!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null)throw new IllegalArgumentException();return uri.toString();}catch(Exception e){throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"请输入有效的 HTTP 或 HTTPS 招聘公告列表地址");}}}
